/** Persistent per-turn records. Locks never silently recover; failed writes leave the prior record intact. */
import { CAMINS } from '../lib/arrel.mjs';
import { checkTaula } from '../gates/porta-olivera.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { DESK, canonical, inside, relativePath, humanZone, hashFile, sha, json, turnPattern, receiptPattern,
  loadContract, saveContract, readContract, resolveRoute, parseDocument, anchored, validateSchema, validateSections, validateRegister } from './core.mjs';

const STORE = '.agents/runtime/turns';
function recordPath(root, id) {
  if (!turnPattern.test(id)) throw new Error('Identificador de torn invàlid');
  const target = path.join(root, STORE, `${id}.json`);
  if (!inside(canonical(root), canonical(target))) throw new Error('Registre fora del repositori');
  return target;
}
export function inventory(root, {files=[]} = {}) {
  const out = {};
  const skip = new Set(['node_modules', '.git', 'dist', '90_arxiu_historic', '.obsidian', 'runtime', '__pycache__']);
  function walk(rel) {
    const file = path.join(root, rel);
    if (!fs.existsSync(file)) return;
    const stat = fs.lstatSync(file);
    if (stat.isSymbolicLink()) { out[rel] = sha(`symlink:${fs.readlinkSync(file)}`); return; }
    if (stat.isDirectory()) {
      for (const e of fs.readdirSync(file).sort()) if (!skip.has(e)) walk(`${rel}/${e}`);
    } else if (stat.isFile()) out[rel] = hashFile(file);
  }
  for (const rel of ['src', 'tooling', 'scripts', 'tests', '.agents', '.codex', '.claude', '.github', '.husky', CAMINS.wiki,
    'package.json', 'package-lock.json', 'AGENTS.md', 'CLAUDE.md', 'vite.config.js', '.gitignore']) walk(rel);
  for (const file of files) {
    const rel=relativePath(root,file);
    if(fs.existsSync(path.join(root,rel))) out[rel]=hashFile(path.join(root,rel));
  }
  delete out['.agents/TORN_ACTIU.json'];
  return out;
}
export function changes(before, after) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].filter(p => before[p] !== after[p]).sort();
}
export function readTurn(root, id, { closed = false, now = Date.now() } = {}) {
  const turn = json(recordPath(root, id));
  if (turn.turn_id !== id || turn.schema !== 'sdp.turn.v1' || !['opened', 'context_loaded', 'planned', 'verified', 'closed'].includes(turn.state)) throw new Error('Registre de torn invàlid');
  if (turn.state === 'closed' && !closed) throw new Error('Torn ja tancat');
  if (turn.state !== 'closed' && (!Number.isFinite(Date.parse(turn.expiresAt)) || Date.parse(turn.expiresAt) <= now)) throw new Error('Torn caducat');
  if (!turn.receipts || !turn.initial || !Array.isArray(turn.history)) throw new Error('Registre de torn incomplet');
  return turn;
}
function atomic(file, value) {
  const tmp = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, {flag:'wx', mode:0o600});
    fs.renameSync(tmp, file);
  } finally { if (fs.existsSync(tmp)) fs.unlinkSync(tmp); }
}
export function mutateTurn(root, id, operation) {
  const file = recordPath(root, id), lock = `${file}.lock`;
  const fd = fs.openSync(lock, 'wx', 0o600);
  try {
    const turn = readTurn(root, id);
    const result = operation(turn);
    turn.revision += 1;
    turn.updatedAt = new Date().toISOString();
    atomic(file, turn);
    return result ?? turn;
  } finally { fs.closeSync(fd); fs.unlinkSync(lock); }
}
function move(turn, state, action) {
  turn.state = state;
  turn.history.push({state, action, at:new Date().toISOString()});
}
export function openTurn(root, { actor = 'agent-local', scope = 'code' } = {}) {
  if (fs.existsSync(path.join(root, '.agents/SDP-LOCK'))) throw new Error('SDP-LOCK actiu');
  if (!['code', 'documents'].includes(scope)) throw new Error('Abast desconegut');
  const contract = loadContract(root, {templates:false});
  const turn_id = `torn_${randomUUID()}`;
  const now = new Date().toISOString();
  const turn = {schema:'sdp.turn.v1', turn_id, actor, scope, state:'opened', revision:0,
    createdAt:now, updatedAt:now, expiresAt:new Date(Date.now()+86400000).toISOString(),
    contractHash:contract.hash, humanInventoryVersion:1, initial:inventory(root), receipts:{}, plan:null, verification:null,
    history:[{state:'opened', action:'open', at:now}]};
  const file = recordPath(root, turn_id);
  fs.mkdirSync(path.dirname(file), {recursive:true});
  fs.writeFileSync(file, `${JSON.stringify(turn, null, 2)}\n`, {flag:'wx', mode:0o600});
  return turn;
}
// Els rebuts de context legacy no tenen fase de creació i conserven el contracte.
export function isActiveReceipt(receipt) {
  if (!Object.hasOwn(receipt, 'creation')) return true;
  const phase = receipt.creation;
  if (!phase || !['prepared', 'committed', 'failed'].includes(phase.state) || !Number.isFinite(Date.parse(phase.preparedAt))) throw new Error('Fase de creació del rebut invàlida');
  if (phase.state === 'failed' && (phase.absent !== true || !Number.isFinite(Date.parse(phase.failedAt)))) throw new Error('Absència de creació fallida no acreditada');
  if (phase.state === 'committed' && (!/^[a-f0-9]{64}$/.test(phase.documentHash || '') || !Number.isFinite(Date.parse(phase.committedAt)))) throw new Error('Creació consolidada sense empremta');
  return phase.state !== 'failed';
}
export function activeReceipts(turn) {
  return Object.values(turn.receipts).filter(receipt => {
    if (isActiveReceipt(receipt)) return true;
    if (!turn.history.some(event => event.action === 'create-failed' && event.receiptId === receipt.id && event.file === receipt.file && event.absent === true && event.at === receipt.creation.failedAt)) throw new Error('Creació fallida sense traça d’absència');
    return false;
  });
}

// Observació física per descriptor: mai llegim un symlink o un hardlink.
function creationFile(root, relative) {
  root = fs.realpathSync(root);
  if (typeof relative !== 'string' || path.isAbsolute(relative) || relative.includes('\\') || relative.split('/').some(p => !p || p === '.' || p === '..')) throw new Error('Ruta de creació documental no regular');
  const parts = relative.split('/');
  const parents = () => {
    let current = root;
    for (const part of parts.slice(0, -1)) {
      current = path.join(current, part);
      try {
        const stat = fs.lstatSync(current);
        if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error('Ruta de creació documental no regular');
      } catch (error) { if (error.code === 'ENOENT') return false; throw error; }
    }
    return true;
  };
  if (!parents()) return { exists: false };
  const file = path.join(root, relative);
  let named;
  try { named = fs.lstatSync(file); } catch (error) { if (error.code === 'ENOENT') return { exists: false }; throw error; }
  const regular = stat => stat.isFile() && !stat.isSymbolicLink() && stat.nlink === 1;
  if (!regular(named)) throw new Error('Ruta de creació documental no regular');
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  try {
    const opened = fs.fstatSync(fd);
    if (!regular(opened) || opened.dev !== named.dev || opened.ino !== named.ino) throw new Error('Ruta de creació documental substituïda');
    if (!parents()) throw new Error('Ruta de creació documental substituïda');
    const raw = fs.readFileSync(fd, 'utf8');
    if (!parents()) throw new Error('Ruta de creació documental substituïda');
    const after = fs.lstatSync(file), last = fs.fstatSync(fd);
    if (!regular(after) || !regular(last) || after.dev !== opened.dev || after.ino !== opened.ino) throw new Error('Ruta de creació documental substituïda');
    return { exists: true, raw };
  } finally { fs.closeSync(fd); }
}
function creationReceipt(turn, reflex) {
  const match = receiptPattern.exec(reflex || '');
  const receipt = match && match[1] === turn.turn_id && turn.receipts[match[2]];
  if (!receipt || receipt.id !== match[2] || receipt.creation?.state !== 'prepared') throw new Error('Creació sense rebut preparat');
  isActiveReceipt(receipt);
  return receipt;
}
function commitPreparedCreation(root, turn, reflex, raw) {
  const receipt = creationReceipt(turn, reflex);
  const observed = creationFile(root, receipt.file);
  const index = creationFile(root, `${DESK}/00_index_escriptori.md`);
  if (!observed.exists || observed.raw !== raw || parseDocument(raw).data.reflex !== reflex || !index.exists || !anchored(index.raw, receipt.file)) throw new Error('Creació pendent: fitxer, empremta o àncora divergent');
  const at = new Date().toISOString();
  receipt.creation = { ...receipt.creation, state: 'committed', committedAt: at, documentHash: sha(raw) };
  turn.verification = null;
  turn.history.push({ action: 'create-committed', receiptId: receipt.id, file: receipt.file, at, hash: sha(raw) });
}
function failPreparedCreation(root, turn, reflex) {
  const receipt = creationReceipt(turn, reflex);
  if (creationFile(root, receipt.file).exists) throw new Error('Creació pendent: el fitxer encara existix');
  const at = new Date().toISOString();
  receipt.creation = { ...receipt.creation, state: 'failed', failedAt: at, absent: true };
  turn.verification = null;
  turn.history.push({ action: 'create-failed', receiptId: receipt.id, file: receipt.file, at, absent: true });
}
export function commitCreation(root, id, reflex, raw) {
  return mutateTurn(root, id, turn => { commitPreparedCreation(root, turn, reflex, raw); });
}
export function failCreation(root, id, reflex) {
  return mutateTurn(root, id, turn => { failPreparedCreation(root, turn, reflex); });
}
/** Consolida només el draft físic del rebut explícit, o acredita l'absència.
 * No genera, substituïx ni elimina cap document; tota la decisió usa un lock.
 */
export function recoverCreation(root, id, { file, reflex }) {
  return mutateTurn(root, id, turn => {
    const receipt = creationReceipt(turn, reflex);
    if (receipt.file !== file || humanZone(file) || !file.startsWith(`${DESK}/`) || path.basename(file) === '00_index_escriptori.md') throw new Error('Rebut de recuperació vinculat a un altre document');
    if (activeReceipts(turn).some(other => other.id !== receipt.id && other.file === file && other.creation?.state === 'prepared')) throw new Error('Creació preparada ambigua');
    const observed = creationFile(root, file);
    if (observed.exists) commitPreparedCreation(root, turn, reflex, observed.raw);
    else failPreparedCreation(root, turn, reflex);
    return { file, reflex, state: receipt.creation.state, turn_id: turn.turn_id };
  });
}
export function deliverContext(root, id, {route:routeId, file, creation = false}) {
  const contract = loadContract(root, {route:routeId}), route = resolveRoute(contract, {route:routeId});
  const rel = relativePath(root, file);
  if (!(route.destins || [DESK]).some(dir=>rel.startsWith(`${dir}/`)) || humanZone(rel) || path.basename(rel) === '00_index_escriptori.md') throw new Error('Destí de document no autoritzat');
  if (!/^\d{6}_\d{4}_[a-z0-9_]+\.md$/.test(path.basename(rel))) throw new Error('Nom termodinàmic invàlid');
  // Convocar agents exigix taula neta també fora d'un hook; una auditoria pot
  // documentar una taula bruta. create revalida ací, encara que ja tinga context.
  if (['prompt.local', 'prompt.consell'].includes(route.id)) {
    const taula = checkTaula(root);
    if (!taula.valid) throw new Error(`Convocatòria amb Escriptori brut:\n${taula.errors.join('\n')}`);
  }
  return mutateTurn(root, id, turn => {
    if (creation) {
      if (creationFile(root, rel).exists) throw new Error('Creació pendent: el fitxer encara existix');
      const contexts = activeReceipts(turn).filter(receipt => receipt.file === rel);
      if (contexts.length) {
        const receipt = contexts[0];
        if (!receiptPattern.test(`sdp:${id}:${receipt.id}`) || turn.receipts[receipt.id] !== receipt) throw new Error('Rebut de context amb identitat divergent');
        if (contexts.length !== 1 || Object.hasOwn(receipt, 'creation')) throw new Error('Context de creació ambigu o ja preparat');
        if (receipt.route !== route.id || receipt.routeVersion !== route.version || receipt.template !== route.plantilla || receipt.templateHash !== route.templateHash || receipt.contractSnapshot !== sha(JSON.stringify(contract))) throw new Error('Context de creació amb contracte o plantilla divergent');
        readContract(root, receipt.contractSnapshot, snapshot => {
          const observed = creationFile(root, snapshot);
          if (!observed.exists) throw new Error('Snapshot de context absent');
          return observed.raw;
        }); // Snapshot immutable, observat sense seguir àlies físics.
        const at = new Date().toISOString();
        receipt.creation = { state: 'prepared', preparedAt: at };
        turn.verification = null;
        turn.state = turn.plan ? 'planned' : 'context_loaded';
        turn.history.push({ state: turn.state, action: 'create-prepared-from-context', receiptId: receipt.id, file: rel, at });
        return { reflex: `sdp:${id}:${receipt.id}`, route, template: route.templateText };
      }
    }
    const receiptId = randomUUID();
    const receipt = {id:receiptId, route:route.id, routeVersion:route.version, file:rel,
      contractSnapshot:saveContract(root,contract), template:route.plantilla, templateHash:route.templateHash, issuedAt:new Date().toISOString()};
    if (creation) receipt.creation = {state:'prepared', preparedAt:new Date().toISOString()};
    turn.receipts[receiptId] = receipt;
    // New context invalidates verification, but retains an already bound plan.
    turn.verification = null;
    move(turn, turn.plan ? 'planned' : 'context_loaded', 'context');
    return {reflex:`sdp:${id}:${receiptId}`, route, template:route.templateText};
  });
}
export function validateDocument(root, content, file, { closed = false, readRecord, readSnapshot } = {}) {
  const errors = [];
  try {
    const parsed = parseDocument(content);
    const rel = relativePath(root, file);
    // The canonical desktop index is structural, never a substitute for a formal document.
    if (rel === `${DESK}/00_index_escriptori.md` && parsed.data.type === 'index') return validateSchema(parsed.data,loadContract(root,{templates:false}).schema);
    const m = typeof parsed.data.reflex === 'string' && receiptPattern.exec(parsed.data.reflex);
    if (!m) {
      errors.push('reflex: cal un rebut persistent emés per document.mjs context');
      errors.push(...validateSchema(parsed.data, loadContract(root, {templates: false}).schema));
    } else {
      const turn = readRecord ? readRecord(m[1]) : readTurn(root, m[1], {closed});
      const receipt = turn.receipts[m[2]];
      if (!receipt || receipt.id !== m[2] || receipt.file !== rel) throw new Error('Rebut absent o vinculat a un altre document');
      if (!isActiveReceipt(receipt)) throw new Error('Rebut de creació fallida: no autoritza cap document');
      if (receipt.creation?.state === 'prepared') throw new Error('Rebut de creació pendent de consolidar');
      const contract = receipt.contractSnapshot ? readContract(root,receipt.contractSnapshot,readSnapshot) : loadContract(root,{route:receipt.route});
      if (!receipt.contractSnapshot && turn.contractHash !== contract.hash) throw new Error('Contracte del rebut caducat');
      errors.push(...validateSchema(parsed.data, contract.schema));
      const route = resolveRoute(contract, {route:receipt.route});
      if (receipt.templateHash !== route.templateHash || receipt.routeVersion !== route.version) throw new Error('Plantilla del rebut canviada');
      if (parsed.data.type !== route.tipus) errors.push('type: no correspon a la ruta del rebut');
      errors.push(...validateSections(parsed.body, route), ...validateRegister(parsed.body, contract));
      if (turn.state === 'closed' && turn.verification?.files?.[rel] !== sha(content)) errors.push('Artefacte modificat després del tancament');
    }
  } catch (e) { errors.push(e.message); }
  return errors;
}
export function bindPlan(root, id, file) {
  const rel = relativePath(root, file);
  const raw = fs.readFileSync(path.join(root, rel), 'utf8');
  const parsed = parseDocument(raw);
  const contract = loadContract(root);
  const errors = validateSchema(parsed.data, contract.schema);
  if (errors.length || parsed.data.type !== 'document') throw new Error(`Pla invàlid: ${errors.join('; ')}`);
  if (!rel.startsWith(`${DESK}/`) || humanZone(rel)) throw new Error('El pla ha de viure a l’Escriptori');
  return mutateTurn(root, id, turn => {
    if (!activeReceipts(turn).length) throw new Error('Cal entregar context actiu abans de vincular el pla');
    turn.plan = {file:rel, hash:sha(raw)};
    turn.verification = null;
    move(turn, 'planned', 'bind-plan');
  });
}
export function checkTurn(root, id, {turn:provided} = {}) {
  const errors = [];
  const turn = provided || readTurn(root, id);
  const contract = loadContract(root,{templates:false});
  if (!Object.values(turn.receipts).every(r=>r.contractSnapshot) && turn.contractHash !== contract.hash) errors.push('Contracte canviat durant el torn');
  if (!turn.plan || !fs.existsSync(path.join(root,turn.plan.file)) || hashFile(path.join(root, turn.plan.file)) !== turn.plan.hash) errors.push(`Pla absent o modificat: ${turn.plan?.file || '(sense pla)'}`);
  if (!['planned', 'verified'].includes(turn.state)) errors.push('El torn encara no està planificat');
  const receipts = activeReceipts(turn);
  const current = inventory(root,{files:receipts.map(r=>r.file)}), changed = changes(turn.initial, current);
  // Explicit ownership avoids importing another agent's documents into this turn.
  // Human-zone and scope checks still use the complete repository delta.
  const owned = turn.ownedPaths ? new Set([...turn.ownedPaths,...receipts.map(r=>r.file)]) : null;
  const documents = new Set([...changed.filter(p=>!humanZone(p)).filter(p=>!turn.relocated?.includes(p)).filter(p=>!owned || owned.has(p)).filter(p => p.startsWith(`${DESK}/`) && p.endsWith('.md')),
    ...receipts.map(r => r.file)]);
  if (turn.scope === 'documents' && changed.some(p => /^(src|tooling|scripts|tests)\//.test(p) || /^package(?:-lock)?\.json$/.test(p))) errors.push('Canvis de codi fora de l’abast documental');
  for (const p of ['.agents/ESTAT.md', '.agents/LEDGER.md']) {
    if (current[p] === turn.initial[p] || !fs.readFileSync(path.join(root,p),'utf8').includes(id)) errors.push(`${p}: falta el relleu d’aquest torn`);
  }
  const humanBefore=turn.humanBaseline?.files || (turn.humanInventoryVersion===1 ? Object.fromEntries(Object.entries(turn.initial).filter(([p])=>humanZone(p))) : null);
  if(!humanBefore) errors.push('Vigilància humana sense inventari inicial; cal una migració explícita observada');
  else for(const file of changes(humanBefore,Object.fromEntries(Object.entries(current).filter(([p])=>humanZone(p))))) errors.push(`Zona humana modificada: ${file}`);
  // Una creació fallida no exigix un document absent; el seu reflex no pot
  // reaparéixer ni quedar ocult per ownership. Un context nou sí que pot usar el path.
  const blockedFailedFiles = new Set();
  for (const receipt of Object.values(turn.receipts)) {
    if (receipt.creation?.state === 'prepared') errors.push(`Creació pendent de consolidar: ${receipt.file}`);
    if (isActiveReceipt(receipt)) continue;
    let observed;
    try { observed = creationFile(root, receipt.file); }
    catch { errors.push(`Creació fallida amb ruta no regular: ${receipt.file}`); blockedFailedFiles.add(receipt.file); continue; }
    if (!observed.exists) continue;
    // El path només pot reaparéixer amb un altre rebut real, també si la nova
    // autoria és aliena al torn. Ownership no pot amagar un reflex inventat.
    errors.push(...validateDocument(root,observed.raw,receipt.file,{readRecord:otherId=>otherId===id?turn:readTurn(root,otherId,{closed:true})}).map(error=>`${receipt.file}: ${error}`));
  }
  const index = fs.readFileSync(path.join(root, DESK, '00_index_escriptori.md'),'utf8');
  for (const file of documents) {
    if (blockedFailedFiles.has(file)) continue;
    if (humanZone(file)) { errors.push(`Zona humana modificada: ${file}`); continue; }
    if (!fs.existsSync(path.join(root,file))) { errors.push(`Document eliminat sense relleu: ${file}`); continue; }
    const raw = fs.readFileSync(path.join(root,file),'utf8');
    errors.push(...validateDocument(root,raw,file,{readRecord:otherId=>otherId===id?turn:readTurn(root,otherId,{closed:true})}).map(e=>`${file}: ${e}`));
    if (file !== `${DESK}/00_index_escriptori.md` && !anchored(index,file)) errors.push(`Document sense àncora: ${file}`);
  }
  return {valid:errors.length===0, errors, current, changed, turn};
}
export function sealTurn(root, id, runChecks, {close = false} = {}) {
  return mutateTurn(root, id, turn => {
    const checked = checkTurn(root, id, {turn});
    if (!checked.valid) throw new Error(checked.errors.join('\n'));
    const result = runChecks(turn);
    if (!result.valid) throw new Error(result.errors.join('\n'));
    const after = inventory(root,{files:activeReceipts(turn).map(r=>r.file)});
    if (changes(checked.current,after).length) throw new Error('La comprovació ha modificat fitxers o hi ha escriptura concurrent');
    turn.verification = {at:new Date().toISOString(), files:after, checks:result.checks};
    move(turn,'verified','verify');
    if (close) move(turn,'closed','close');
    return {valid:true, turn_id:id, state:turn.state, checks:result.checks};
  });
}

// Ownership is explicit; absence keeps the conservative legacy whole-tree check.
export function ownPaths(root,id,files) {
  const paths=files.map(file=>relativePath(root,file));
  if(paths.some(humanZone)) throw new Error('No es pot reclamar la zona humana');
  return mutateTurn(root,id,turn=>{
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]),...paths])];
    turn.verification=null;
    turn.history.push({action:'own-paths',files:paths,at:new Date().toISOString()});
  });
}
// A handoff registers a move already performed; it never fabricates a past reading.
export function handoffDocument(root,id,from,to) {
  const source=relativePath(root,from), target=relativePath(root,to);
  if(humanZone(source)||humanZone(target)) throw new Error('Zona humana protegida');
  if(![DESK,CAMINS.actes,CAMINS.arxiuHistoric].some(dir=>target.startsWith(`${dir}/`))) throw new Error('Destí de relleu no autoritzat');
  if(fs.existsSync(path.join(root,source))) throw new Error('La ruta original encara existeix');
  const raw=fs.readFileSync(path.join(root,target),'utf8'), digest=sha(raw);
  const match=receiptPattern.exec(parseDocument(raw).data.reflex||'');
  if(!match||match[1]!==id) throw new Error('Identitat del relleu divergent');
  return mutateTurn(root,id,turn=>{
    const receipt=turn.receipts[match[2]];
    const prior = receipt?.file===target && receipt.moves?.find(move=>move.from===source && move.to===target && move.hash===digest);
    if(!receipt || (receipt.file!==source && !prior)) throw new Error('Rebut del relleu absent');
    if (!isActiveReceipt(receipt) || receipt.creation?.state === 'prepared') throw new Error('Rebut de relleu sense creació consolidada');
    if(turn.plan?.file===source && turn.plan.hash!==digest) throw new Error('Pla modificat durant el relleu');
    // El reflex identifica el rebut immutable que va fer nàixer el document.
    // Captura IDs exactes: un context posterior per a reutilitzar source no és
    // cap lectura d'este arxiu. Legacy: prefix d'emissió, sense fiar-se del rellotge.
    const emitted = Object.values(turn.receipts);
    const original = emitted.slice(0, emitted.indexOf(receipt)+1).filter(candidate=>
      isActiveReceipt(candidate) && candidate.file===source && candidate.route===receipt.route && candidate.contractSnapshot===receipt.contractSnapshot);
    const receiptIds = prior?.receiptIds || original.map(candidate=>candidate.id);
    for(const owned of emitted.filter(candidate=>isActiveReceipt(candidate) && candidate.file===source && receiptIds.includes(candidate.id))) {
      owned.file=target;
      owned.moves=[...(owned.moves||[]),{from:source,to:target,hash:digest,at:new Date().toISOString(),receiptIds}];
    }
    if(turn.plan?.file===source) turn.plan.file=target;
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]).filter(p=>p!==source),target])];
    // Preserve source history, while recognising that its absence is an intentional handoff.
    turn.relocated=[...(turn.relocated||[]),source];
    turn.verification=null;
    move(turn,turn.plan?'planned':'context_loaded','handoff');
  });
}
export function protectedTurnFiles(root) {
  const dir=path.join(root,STORE), out=new Set();
  if(!fs.existsSync(dir)) return out;
  for(const name of fs.readdirSync(dir).filter(n=>n.endsWith('.json'))) {
    const turn=json(path.join(dir,name));
    if(!turnPattern.test(turn.turn_id)||!Array.isArray(turn.history)||!turn.receipts) throw new Error(`Torn il·legible: ${name}`);
    // Closed receipts are protected too until an explicit archival handoff is supported.
    if(turn.plan?.file) out.add(turn.plan.file);
    for(const receipt of activeReceipts(turn)) out.add(receipt.file);
  }
  return out;
}

export function startHumanWatch(root,id) {
 return mutateTurn(root,id,turn=>{
  if(turn.humanInventoryVersion===1||turn.humanBaseline) throw new Error('Inventari humà ja establit; no es pot reiniciar');
  turn.humanBaseline={at:new Date().toISOString(),provenance:'observed-at-upgrade',files:Object.fromEntries(Object.entries(inventory(root)).filter(([file])=>humanZone(file)))};
  turn.history.push({action:'start-human-watch',at:turn.humanBaseline.at,note:'Observació actual; no acredita vigilància anterior ni autoria dels canvis previs.'});
 });
}

export function acknowledgeHumanZoneChanges(root, id, note = 'Reconeixement explícit de canvis a la zona humana') {
  return mutateTurn(root, id, turn => {
    if (!turn.humanBaseline) throw new Error('No hi ha vigilància humana activa al torn');
    const currentHumanZone = Object.fromEntries(Object.entries(inventory(root)).filter(([file]) => humanZone(file)));
    const changedFiles = changes(turn.humanBaseline.files, currentHumanZone);
    if (!changedFiles.length) throw new Error('No hi ha canvis a la zona humana per a reconéixer');

    turn.humanBaseline.files = currentHumanZone;
    turn.humanBaseline.at = new Date().toISOString();
    turn.humanBaseline.provenance = 'acknowledged';
    turn.verification = null;
    turn.history.push({ action: 'acknowledge-human-zone-changes', files: changedFiles, at: turn.humanBaseline.at, note });
  });
}

/** P13 authority: bounded documentary commands are state mutations, never knownRead. */
import fs from 'node:fs';
import path from 'node:path';
import {DESK, humanZone, loadContract, resolveRoute, parseDocument, validateSchema, turnPattern, receiptPattern, sha} from './core.mjs';
import {readTurn, validateDocument, activeReceipts, isActiveReceipt} from './turns.mjs';
import {normalizeShellCommand} from '../gates/mutation-policy.mjs';

// A deliberately small argv language. No shell expansion, escapes, globs or operators.
export function documentArgv(command) {
  if (typeof command !== 'string' || !command.trim() || /[\0\r\n$`\\;&|<>]/.test(command) || /[^\S \t]/u.test(command)) throw new Error('Shell documental no literal');
  const words=[]; let word='', quote=null, started=false;
  for (const character of command.trim()) {
    if (quote) {
      if (character===quote) quote=null; else word+=character;
      continue;
    }
    if (character==='"'||character==="'") {quote=character;started=true;continue;}
    if (character === ' ' || character === '\t') {
      if(started){words.push(word);word='';started=false;}
    } else {
      if(/[(){}[\]*?!#~]/.test(character)) throw new Error('Expansió de shell no admesa');
      word+=character;started=true;
    }
  }
  if(quote) throw new Error('Cometes incompletes');
  if(started)words.push(word);
  return words;
}
function physical(root, relative) {
  if(typeof relative!=='string'||!relative||path.isAbsolute(relative)||relative.includes('\\')||relative.split('/').some(part=>!part||part==='.'||part==='..')) throw new Error('Ruta documental no canònica');
  let current=root;
  for(const part of relative.split('/')) {
    current=path.join(current,part);
    try {
      const stat=fs.lstatSync(current);
      if(stat.isSymbolicLink()||(stat.isFile()&&stat.nlink!==1)) throw new Error('Ruta documental amb symlink/hardlink');
    } catch(error){if(error.code!=='ENOENT')throw error;}
  }
  return current;
}
function flags(words, permitted, required=[]) {
  const values={};
  for(let i=0;i<words.length;i+=2){
    const flag=words[i];
    if(!/^--[a-z-]+$/.test(flag)||!permitted.includes(flag.slice(2))||Object.hasOwn(values,flag.slice(2))) throw new Error(`Flag documental no autoritzat/repetit: ${flag}`);
    const value=words[i+1];
    if(typeof value!=='string'||!value.trim()||value.startsWith('--'))throw new Error(`Valor absent: ${flag}`);
    values[flag.slice(2)]=value;
  }
  if(required.some(key=>!values[key]))throw new Error('Falten paràmetres documentals obligatoris');
  return values;
}
function documentPath(root, file, {named=true}={}) {
  const target=physical(root,file);
  if(!file.startsWith(`${DESK}/`)||humanZone(file)||!file.endsWith('.md'))throw new Error('Destí fora de l’Escriptori documental');
  if(named&&!/^\d{6}_\d{4}_[a-z0-9_]+\.md$/.test(path.basename(file)))throw new Error('Nom documental invàlid');
  return target;
}
/** null = unrelated command; a matched invalid command throws. No writes occur here. */
export function authorizeDocumentCommand(payload, root) {
  if(!['Bash','exec_command','run_command'].includes(payload.tool_name))return null;
  const command=normalizeShellCommand(payload,root);
  // Parse every candidate, including quoted spellings; all other commands stay denied by the host.
  let argv;
  try{argv=documentArgv(command);}catch(error){if(command.includes('document.mjs')||command.includes('obrir_torn.mjs'))throw error;return null;}
  if(argv[0]!=='node'||!['tooling/wiki/document.mjs','tooling/gates/obrir_torn.mjs'].includes(argv[1]))return null;
  root=fs.realpathSync(root);
  if(!fs.statSync(physical(root,argv[1])).isFile())throw new Error('CLI documental no regular');
  physical(root,'.agents/runtime');physical(root,'.agents/runtime/turns');physical(root,'.agents/runtime/contracts');
  if(argv[1]==='tooling/gates/obrir_torn.mjs') {
    const opts=flags(argv.slice(2),['actor','scope'],['scope']);
    if(!['documents','code'].includes(opts.scope))throw new Error('Abast documental desconegut');
    if(opts.actor&&opts.actor.length>120)throw new Error('Actor massa llarg');
    loadContract(root,{templates:false});
    return {kind:'document-mutation',command:'open'};
  }
  const action=argv[2];
  const specifications={recover:[['turn-id','file','reflex'],['turn-id','file','reflex']],context:[['turn-id','route','file'],['turn-id','route','file']],create:[['turn-id','route','file','title','description','actor'],['turn-id','route','file','title','description']],plan:[['turn-id','file'],['turn-id','file']],check:[['file'],['file']],own:[['turn-id','file'],['turn-id','file']]};
  if(!Object.hasOwn(specifications,action))throw new Error('Operació fora del circuit documental ordinari');
  const opts=flags(argv.slice(3),...specifications[action]);
  const file=documentPath(root,opts.file,{named:action!=='check'});
  if(action==='check')return {kind:'read',command:action,file:opts.file};
  if(!turnPattern.test(opts['turn-id']))throw new Error('Identificador de torn invàlid');
  physical(root,`.agents/runtime/turns/${opts['turn-id']}.json`);
  physical(root,`.agents/runtime/turns/${opts['turn-id']}.json.lock`);
  const turn=readTurn(root,opts['turn-id']);
  if(action==='context'||action==='create') {
    const contract=loadContract(root,{route:opts.route}), route=resolveRoute(contract,{route:opts.route});
    physical(root,`.agents/runtime/contracts/${sha(JSON.stringify(contract))}.json`);
    if(!(route.destins||[DESK]).some(dir=>opts.file.startsWith(`${dir}/`)))throw new Error('Destí divergent de ruta');
    if(action==='create') {
      const contexts=activeReceipts(turn).filter(receipt=>receipt.route===route.id&&receipt.file===opts.file);
      if(!contexts.length)throw new Error('Cal context entregat per a este document abans de create');
      if(contexts.some(receipt=>!receiptPattern.test(`sdp:${turn.turn_id}:${receipt.id}`)||turn.receipts[receipt.id]!==receipt))throw new Error('Rebut de context amb identitat divergent');
      if(fs.existsSync(file))throw new Error('create no sobreescriu documents');
      if(opts.title.length>300||opts.description.length>1000||opts.actor?.length>120)throw new Error('Metadades documentals massa llargues');
      const errors=validateSchema({...route.output,description:opts.description,visibility:'private'},contract.schema);
      if(errors.length)throw new Error(errors.join('; '));
      physical(root,`${DESK}/00_index_escriptori.md`);
      physical(root,'.agents/runtime/document-create.lock');
    }
  } else if(action==='recover') {
    const match=receiptPattern.exec(opts.reflex),receipt=match&&match[1]===turn.turn_id&&turn.receipts[match[2]];
    if(!receipt||receipt.id!==match[2]||receipt.file!==opts.file||receipt.creation?.state!=='prepared'||!isActiveReceipt(receipt))throw new Error('Recuperació sense rebut preparat del document');
    if(activeReceipts(turn).some(other=>other.id!==receipt.id&&other.file===opts.file&&other.creation?.state==='prepared'))throw new Error('Creació preparada ambigua');
    physical(root,`${DESK}/00_index_escriptori.md`);
  } else if(action==='plan') {
    const content=fs.readFileSync(file,'utf8');
    const parsed=parseDocument(content);
    const errors=validateDocument(root,content,opts.file,{closed:true});
    if(parsed.data.type!=='document'||errors.length)throw new Error(`Pla documental invàlid: ${errors.join('; ')}`);
    if(!activeReceipts(turn).length)throw new Error('Cal context actiu abans de vincular pla');
  } else if(!activeReceipts(turn).some(receipt=>receipt.file===opts.file)&&turn.plan?.file!==opts.file)throw new Error('own només per a documents amb rebut o pla d’este torn');
  return {kind:'document-mutation',command:action,file:opts.file,turnId:turn.turn_id};
}

#!/usr/bin/env node
import { esMain } from '../lib/arrel.mjs';
/** Explicit, host-independent delivery of templates and generation of indexed drafts. */
import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import { ROOT, options } from '../documental/cli.mjs';
import { loadContract, validateSchema, parseDocument } from '../documental/core.mjs';
import { checkDraftDestinations, writeIndexedDraft } from '../documental/draft-write.mjs';
import { deliverContext, bindPlan, validateDocument, ownPaths, handoffDocument, commitCreation, failCreation, recoverCreation } from '../documental/turns.mjs';

export function draft(delivery, {title, description, actor='agent-local'}) {
  const now = new Date().toISOString();
  const data = {...delivery.route.output, description, visibility:'private', reflex:delivery.reflex};
  const values = {Identificador:delivery.reflex, 'Versió del document':'1.0.0', Entorn:'entorn-dev-local',
    'Creació':now, 'Modificació':now, Propietari:actor, 'Aprovació humana':'pendent', Plantilla:`${delivery.route.plantilla} (v${delivery.route.version})`, 'Model IA':'[pendent]', 'Tokens consumits':'[pendent]'};
  const body = delivery.route.seccions.map(section => {
    const content = delivery.route.fixedBlocks?.[section] ?? (section === 'Registre' ? '| Camp | Valor |\n| --- | --- |\n'+Object.entries(values).map(([k,v])=>`| ${k} | ${v} |`).join('\n')
      : section === 'Acte reflex' ? `Plantilla entregada: ${delivery.route.plantilla}; SHA-256 ${delivery.route.templateHash}. El rebut acredita entrega, no comprensió.`
      : section === 'Historial' ? `${now}: esborrany creat; contingut i verificació pendents.`
      : section === 'Vincles' ? '- [[00_index]]\n- [[00_index_escriptori]]' : '[pendent]');
    const sectionId=delivery.route.sectionIds?.[section];
    return `${sectionId ? `<!-- SDP:SECTION ${sectionId} -->\n` : ''}## ${section}\n\n${content}`;
  }).join('\n\n');
  const templateBody=parseDocument(delivery.template).body;
  const prelude=/^# [^\n]*\n([\s\S]*?)(?=^## )/m.exec(templateBody)?.[1]?.trim() || '';
  return `---\n${yaml.dump(data,{schema:yaml.JSON_SCHEMA,lineWidth:-1,noRefs:true})}---\n# ${title}\n\n${prelude ? prelude+'\n\n' : ''}${body}\n`;
}
export function createDraft(root, id, opts) {
  if (!opts.title || !opts.description) throw new Error('Cal --title i --description');
  root = fs.realpathSync(root);
  const file = path.resolve(root, opts.file);
  checkDraftDestinations(root, file);
  const delivery = deliverContext(root,id,{...opts, creation:true});
  try {
    const raw = draft(delivery,opts);
    const contract = loadContract(root,{templates:false});
    const errors = validateSchema({...delivery.route.output,description:opts.description,visibility:'private',reflex:delivery.reflex},contract.schema);
    if (errors.length) throw new Error(errors.join('\n'));
    writeIndexedDraft(root, file, raw, { requireCleanTable: ['prompt.local', 'prompt.consell'].includes(delivery.route.id) });
    commitCreation(root,id,delivery.reflex,raw);
    return {file:opts.file,reflex:delivery.reflex,state:'draft',note:'Completa les seccions [pendent] abans de validar.'};
  } catch (error) {
    // Si hi ha un fitxer parcial/concurrent o falla la metadata, el rebut queda
    // preparat i visible per a recuperació. Mai certifiquem una absència falsa.
    try { failCreation(root,id,delivery.reflex); } catch { /* pendent, sense eliminar res */ }
    throw error;
  }
}
async function main() {
  const o=options(), root=path.resolve(o.arrel || ROOT), command=o._[0];
  let result;
  if(o.help || !command) {
    console.log('Ús: document.mjs context|create|recover|plan|check|own|handoff|import --turn-id ID --route ID --file CAMÍ\ncreate: --title TÍTOL --description DESCRIPCIÓ [--actor NOM]\nrecover: --turn-id ID --file CAMÍ --reflex REBUT (consolida el draft present o acredita absència; no elimina fitxers)\nown: --file CAMÍ (repetix la comanda per cada fitxer)\nhandoff: --file ORIGEN --to DESTÍ (després del moviment explícit)\nRutes: '+loadContract(root,{templates:false}).router.rutes.map(r=>r.id).join(', '));
    return;
  }
  if(command==='recover') result=recoverCreation(root,o['turn-id'],{file:o.file,reflex:o.reflex});
  else if(command==='import') {const {importDocument}=await import('../documental/import.mjs');result=importDocument(root,o['turn-id'],o);}
  else if(command==='own') result=ownPaths(root,o['turn-id'],[o.file]);
  else if(command==='handoff') result=handoffDocument(root,o['turn-id'],o.file,o.to);
  else if (command==='context') {
    const d=deliverContext(root,o['turn-id'],{route:o.route,file:o.file});
    result={reflex:d.reflex,route:d.route.id,template:d.template};
  } else if(command==='create') result=createDraft(root,o['turn-id'],{route:o.route,file:o.file,title:o.title,description:o.description,actor:o.actor});
  else if(command==='plan') {const t=bindPlan(root,o['turn-id'],o.file);result={turn_id:t.turn_id,state:t.state,plan:t.plan};}
  else if(command==='check') {const errors=validateDocument(root,fs.readFileSync(path.join(root,o.file),'utf8'),o.file,{closed:true});result={valid:!errors.length,errors};process.exitCode=errors.length?1:0;}
  else throw new Error('Ús: document.mjs context|create|recover|plan|check --turn-id ID --route ID --file CAMÍ');
  console.log(JSON.stringify(result,null,2));
}
if (esMain(import.meta.url)) {
  main().catch(e=>{console.error(e.message);process.exitCode=1;});
}

